{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Loteprednol etabonate, a corticosteroid ester prodrug, showed very low oral bioavailability in healthy volunteers after a 40 mg oral dose, supporting low F for the similarly esterified/acetal corticosteroid prodrug query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Beclomethasone dipropionate, an inhaled corticosteroid diester prodrug, is reported to have an oral bioavailability of 15%, indicating extensive first-pass metabolism and supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Mometasone, a halogenated corticosteroid with very low oral bioavailability (<1%), supports low F for the query, which shares lipophilic, metabolically labile corticosteroid prodrug character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Deflazacort, the closest scored analogue, had 68% absolute oral bioavailability in volunteers; this high-F corticosteroid prodrug evidence is contradictory but has limited transfer because deflazacort is an oral prodrug with a different metabolic design.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Prednisolone, a high-bioavailability corticosteroid (~80%), is contradictory evidence for low F, but its simple dihydroxy steroid structure lacks the ester/acetal prodrug and first-pass liabilities of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C54"],
      "claim": "Dexamethasone, with approximately 62% oral bioavailability, is contradictory evidence, but it is a non-prodrug corticosteroid and less structurally similar to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low: the query is a lipophilic corticosteroid 21-ester/16,17-acetal prodrug (ciclesonide-like) intended for inhalation; structurally relevant inhaled corticosteroid ester prodrugs (loteprednol, beclomethasone dipropionate, mometasone) show low-to-negligible oral bioavailability due to first-pass metabolism, outweighing high-F oral corticosteroids that lack these prodrug/inactivation features.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule is present in the supplied evidence.",
    "Prodrug activation and active metabolite exposure are not captured by parent-drug F records.",
    "Conflicting high-F oral corticosteroid analogues are less transferable but not directly ruled out by experimental data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

